macro_rules! deps {
    () => {
        Level!();
        Kind!();
        FieldSet!();
        Subscriber!();
    };
}

macro_rules! Metadata {
    () => {
        deps!();
        # [doc = " Metadata describing a [span] or [event]."] # [doc = ""] # [doc = " All spans and events have the following metadata:"] # [doc = " - A [name], represented as a static string."] # [doc = " - A [target], a string that categorizes part of the system where the span"] # [doc = "   or event occurred. The `tracing` macros default to using the module"] # [doc = "   path where the span or event originated as the target, but it may be"] # [doc = "   overridden."] # [doc = " - A [verbosity level]. This determines how verbose a given span or event"] # [doc = "   is, and allows enabling or disabling more verbose diagnostics"] # [doc = "   situationally. See the documentation for the [`Level`] type for details."] # [doc = " - The names of the [fields] defined by the span or event."] # [doc = " - Whether the metadata corresponds to a span or event."] # [doc = ""] # [doc = " In addition, the following optional metadata describing the source code"] # [doc = " location where the span or event originated _may_ be provided:"] # [doc = " - The [file name]"] # [doc = " - The [line number]"] # [doc = " - The [module path]"] # [doc = ""] # [doc = " Metadata is used by [`Subscriber`]s when filtering spans and events, and it"] # [doc = " may also be used as part of their data payload."] # [doc = ""] # [doc = " When created by the `event!` or `span!` macro, the metadata describing a"] # [doc = " particular event or span is constructed statically and exists as a single"] # [doc = " static instance. Thus, the overhead of creating the metadata is"] # [doc = " _significantly_ lower than that of creating the actual span. Therefore,"] # [doc = " filtering is based on metadata, rather than on the constructed span."] # [doc = ""] # [doc = " ## Equality"] # [doc = ""] # [doc = " In well-behaved applications, two `Metadata` with equal"] # [doc = " [callsite identifiers] will be equal in all other ways (i.e., have the same"] # [doc = " `name`, `target`, etc.). Consequently, in release builds, [`Metadata::eq`]"] # [doc = " *only* checks that its arguments have equal callsites. However, the equality"] # [doc = " of `Metadata`'s other fields is checked in debug builds."] # [doc = ""] # [doc = " [span]: super::span"] # [doc = " [event]: super::event"] # [doc = " [name]: Self::name"] # [doc = " [target]: Self::target"] # [doc = " [fields]: Self::fields"] # [doc = " [verbosity level]: Self::level"] # [doc = " [file name]: Self::file"] # [doc = " [line number]: Self::line"] # [doc = " [module path]: Self::module_path"] # [doc = " [`Subscriber`]: super::subscriber::Subscriber"] # [doc = " [callsite identifiers]: Self::callsite"] pub struct Metadata < 'a > { # [doc = " The name of the span described by this metadata."] name : & 'static str , # [doc = " The part of the system that the span that this metadata describes"] # [doc = " occurred in."] target : & 'a str , # [doc = " The level of verbosity of the described span."] level : Level , # [doc = " The name of the Rust module where the span occurred, or `None` if this"] # [doc = " could not be determined."] module_path : Option < & 'a str > , # [doc = " The name of the source code file where the span occurred, or `None` if"] # [doc = " this could not be determined."] file : Option < & 'a str > , # [doc = " The line number in the source code file where the span occurred, or"] # [doc = " `None` if this could not be determined."] line : Option < u32 > , # [doc = " The names of the key-value fields attached to the described span or"] # [doc = " event."] fields : field :: FieldSet , # [doc = " The kind of the callsite."] kind : Kind , }
    };
}

Metadata!()